/// <summary>
/// AVADAIReportCache
/// </summary>
class AVADAIReportCache
{
    const GlobalObjectCacheScope AVADAIAllDaiTransfDefIdsCache = "AVADAIAllDaiTransfDefIdsCache";

}

Method.Source:
/// <summary>
/// clear the cache
/// </summary>
public static Container clearCacheAllDaiTransfDefIds()
{
    SysGlobalObjectCache        CacheAllDaiTransfDefIds;
    container                   CacheResultAllDaiTransfDefIds;
    container                   allDaiTransfDefIds;

    if(classFactory)
    {
        CacheAllDaiTransfDefIds     = classFactory.globalObjectCache();
    }
    else
    {
        CacheAllDaiTransfDefIds     = new SysGlobalObjectCache();
    }

    CacheResultAllDaiTransfDefIds   = CacheAllDaiTransfDefIds.find(AVADAIAllDaiTransfDefIdsCache,[curExt()]);

    if ( CacheResultAllDaiTransfDefIds != conNull() )
    {
        CacheAllDaiTransfDefIds.remove(AVADAIAllDaiTransfDefIdsCache,[curExt()]);
    }

    return allDaiTransfDefIds;
}

/// <summary>
/// get a container with all transfDefIds of the module
/// </summary>
public static Container getAllDAITransfDefIds()
{
    SysGlobalObjectCache    CacheAllDaiTransfDefIds;
    container               CacheResultAllDaiTransfDefIds;
    container               allDaiTransfDefIds;

    if(classFactory)
    {
        CacheAllDaiTransfDefIds = classFactory.globalObjectCache();
    }
    else
    {
        CacheAllDaiTransfDefIds = new SysGlobalObjectCache();
    }

    CacheResultAllDaiTransfDefIds = CacheAllDaiTransfDefIds.find(AVADAIAllDaiTransfDefIdsCache,[curExt()]);

    if ( CacheResultAllDaiTransfDefIds == conNull() )
    {
        AVADAIReport    AVADAIReport;
        Map             tmpMap = new map(Types::String,Types::String);
        MapEnumerator   mapEnumerator;

        //fill the cache
        while select ReportTransfDefId, MetadataTransfDefId from AVADAIReport
        {
            tmpMap.insert(AVADAIReport.ReportTransfDefId,"1");
            tmpMap.insert(AVADAIReport.MetadataTransfDefId,"1");
        }

        mapEnumerator = new MapEnumerator(tmpMap);

        while (MapEnumerator.moveNext())
        {
            allDaiTransfDefIds += MapEnumerator.currentKey();
        }

        CacheAllDaiTransfDefIds.insert(AVADAIAllDaiTransfDefIdsCache,[curExt()],[allDaiTransfDefIds]);
    }
    // Key is found in the cache, and is in the cnResult container.
    else    
    {
        allDaiTransfDefIds = conPeek(CacheResultAllDaiTransfDefIds, 1);
    }

    return allDaiTransfDefIds;
}

/// <summary>
/// check the exist of the transdefId
/// </summary>
/// <param name = "_transfDefId">_transfDefId</param>
/// <returns>true or false</returns>
public static boolean existDAITransfDefIds(AVAMSQTransfDefId _transfDefId)
{
    Container allDaiTransfDefIds;
    boolean   ret = false;

    allDaiTransfDefIds = AVADAIReportCache::getAllDAITransfDefIds();

    for(int ii=1;ii <= conLen(allDaiTransfDefIds);ii++)
    {
        if(conPeek(allDaiTransfDefIds,ii) == _transfDefId)
        {
            ret=true;
            break;
        }
    }

    return ret;
}
